docUrl:
{{
  (function() {
    const url = Get_Devis_Detail.data[0]?.Lien_PDF;
    if (!url) return "";

    // Si c'est un lien de téléchargement Google Drive, on le transforme en mode "Preview"
    if (url.includes("uc?id=")) {
      const fileId = url.split("id=")[1].split("&")[0];
      return "https://drive.google.com/file/d/" + fileId + "/preview";
    }

    return url;
  })()
}}
